// Code generated by Buffy for zai-proxy — auto-rebless module.
// See internal/zbridge/qmint.go for the QBless lifetime model.
//
// This module adds a background canary probe goroutine that periodically
// verifies the blessed Q is still alive — WITHOUT spawning Chrome (reuses
// the in-process tryCompute path). When N consecutive probes FAIL, the Q
// is marked "degrading" and a `q-bless` subprocess is spawned to re-bless.
// On success, the new qbless.json is atomically swapped in.
//
// Config (env vars):
//   QBLESS_AUTO_REBLESS=0          disable auto-rebless (default: on)
//   QBLESS_PROBE_INTERVAL=10m       background probe interval (default: 10m)
//   QBLESS_DEGRADING_THRESHOLD=2   consecutive FAIL probes before rebless
//   QBLESS_BINARY=q-bless          path to q-bless binary (default: "./q-bless" or PATH lookup)
//   QBLESS_REBLESS_TIMEOUT=120s     max time to wait for q-bless subprocess
//   QBLESS_PROBE_TIMEOUT=30s       max time for a single in-process canary probe
//   QFARM_RESERVE_TARGET=20        tokens.sqlite reserve size after refill (default 20)

package zbridge

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"math/rand"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"sync"
	"time"
)

// --- auto-rebless state ---------------------------------------------------

var (
	autoReblessOnce       sync.Once
	autoReblessProbeMu    sync.Mutex // serializes background probes vs live requests
	autoReblessFailCount  int        // consecutive probe FAILs
	autoReblessReblessing bool       // true while a rebless subprocess is in flight
	autoReblessMu         sync.Mutex // guards autoReblessReblessing

	autoReblessTriggers    int       // consecutive failed rebless attempts (drives backoff)
	autoReblessLastTrigger time.Time // time of the last rebless attempt (any outcome)
)

// AutoReblessConfig holds env-driven configuration for the auto-rebless
// background probe. All values are resolved once at startup.
type AutoReblessConfig struct {
	Enabled            bool
	ProbeInterval      time.Duration
	DegradingThreshold int
	QblessBinary       string
	ReblessTimeout     time.Duration
	ProbeTimeout       time.Duration
	ReserveTarget      int
}

// resolveAutoReblessConfig reads env vars and returns the effective config.
// Reads at call time — tests can set env vars before calling.
func resolveAutoReblessConfig() AutoReblessConfig {
	cfg := AutoReblessConfig{
		Enabled:            os.Getenv("QBLESS_AUTO_REBLESS") != "0",
		ProbeInterval:      10 * time.Minute,
		DegradingThreshold: 2,
		QblessBinary:       "q-bless",
		ReblessTimeout:     120 * time.Second,
		ProbeTimeout:       30 * time.Second,
		ReserveTarget:      qfarmReserveTarget,
	}
	if v := os.Getenv("QBLESS_PROBE_INTERVAL"); v != "" {
		if d, err := time.ParseDuration(v); err == nil && d > 0 {
			cfg.ProbeInterval = d
		}
	}
	if v := os.Getenv("QBLESS_DEGRADING_THRESHOLD"); v != "" {
		var n int
		if _, err := fmt.Sscanf(v, "%d", &n); err == nil && n > 0 {
			cfg.DegradingThreshold = n
		}
	}
	if v := os.Getenv("QBLESS_BINARY"); v != "" {
		cfg.QblessBinary = v
	}
	if v := os.Getenv("QBLESS_REBLESS_TIMEOUT"); v != "" {
		if d, err := time.ParseDuration(v); err == nil && d > 0 {
			cfg.ReblessTimeout = d
		}
	}
	if v := os.Getenv("QBLESS_PROBE_TIMEOUT"); v != "" {
		if d, err := time.ParseDuration(v); err == nil && d > 0 {
			cfg.ProbeTimeout = d
		}
	}
	if v := os.Getenv("QFARM_RESERVE_TARGET"); v != "" {
		var n int
		if _, err := fmt.Sscanf(v, "%d", &n); err == nil && n > 0 {
			cfg.ReserveTarget = n
		}
	}
	return cfg
}

// --- background probe ----------------------------------------------------

// QFARM_PRE_AGE: proactive rebless age. Z.AI kills a Q somewhere between
// ~70 and ~90 minutes (observed 2026-09-10: dead at 1.4h). Waiting for two
// probe FAILs costs a mint outage window (breaker 3m + operator). Rotating
// BEFORE the observed death band, gated on a canary PASS of the new Q,
// makes the swap zero-downtime: the dead Q is never used because it never
// dies while live.
const qfarmPreAge = 70 * time.Minute

// qfarmReserveTarget tops up the tokens.sqlite emergency reserve to this
// many tokens after every successful rebless (and at startup when reserve
// is empty). 20 covers ~20 cold captcha mints — enough to ride out a
// Chromium-less rebless failure without the "reserve empty" outage seen
// 2026-09-10.
const qfarmReserveTarget = 20

// StartAutoRebless launches the background canary probe goroutine (once).
// Safe to call multiple times — only the first call starts the goroutine.
func StartAutoRebless() {
	autoReblessOnce.Do(func() {
		cfg := resolveAutoReblessConfig()
		if !cfg.Enabled {
			logInfo("[AutoRebless] disabled (set QBLESS_AUTO_REBLESS=0 to disable)")
			return
		}
		logOperational(fmt.Sprintf("[AutoRebless] enabled — probe every %s, threshold %d, binary %q",
			cfg.ProbeInterval, cfg.DegradingThreshold, cfg.QblessBinary))
		go autoReblessLoop(cfg)
	})
}

// autoReblessLoop runs the background probe cycle. It sleeps ProbeInterval
// between probes and triggers rebless when failCount reaches the threshold.
func autoReblessLoop(cfg AutoReblessConfig) {
	// Initial probe after a short startup delay (let the proxy warm up).
	time.Sleep(30 * time.Second)
	// Run one probe immediately on startup.
	autoReblessProbeCycle(cfg)
	for {
		// Jitter +-10% around ProbeInterval: avoids lockstep probe/rotate
		// patterns against Log1 if several proxies run on one host.
		frac := 0.9 + 0.2*rand.Float64()
		time.Sleep(time.Duration(float64(cfg.ProbeInterval) * frac))
		autoReblessProbeCycle(cfg)
	}
}

// autoReblessProbeCycle runs a single canary probe and triggers rebless if
// the fail count crosses the threshold.
func autoReblessProbeCycle(cfg AutoReblessConfig) {
	// Don't probe while a rebless is in flight.
	autoReblessMu.Lock()
	if autoReblessReblessing {
		autoReblessMu.Unlock()
		return
	}
	autoReblessMu.Unlock()

	s := qblessLoad()
	if s == nil {
		// No session file — nothing to probe. If auto-rebless is on and
		// there's no session, trigger a rebless immediately.
		logInfo("[AutoRebless] no blessed session found — triggering initial rebless")
		autoReblessTrigger(cfg)
		return
	}

	ctx, cancel := context.WithTimeout(context.Background(), cfg.ProbeTimeout)
	defer cancel()

	// Serialize with live requests: acquire the probe mutex so we don't
	// race with a real tryCompute that's feeding qblessReportVerifyQ.
	// NOTE: autoReblessTrigger ALSO takes this mutex (around its env swap +
	// post-rebless canary), so it must NEVER be called while this function
	// holds it — Go mutexes are not reentrant. The threshold check below
	// therefore releases the mutex first (probePass scoped, not a bare
	// Lock/defer Unlock) and triggers outside the critical section. The
	// 2026-09-10 incident: probe FAIL(2/2) → trigger → Lock() again
	// deadlocked the rebless goroutine forever; q-bless ran (18.4s), the
	// fresh session sat in /tmp, the swap never happened, and every captcha
	// mint kept failing with "empty payload" while the proxy looked alive.
	probePass := false
	thresholdReached := false
	func() {
		autoReblessProbeMu.Lock()
		defer autoReblessProbeMu.Unlock()
		probePass = autoReblessInProcessCanary(ctx, s, cfg.ProbeTimeout)
	}()
	if probePass {
		autoReblessFailCount = 0
		// QFARM pre-emptive rotation: the canary PASSes but the Q is old
		// enough to be near the observed death band (~70-90min). Rotate NOW
		// while minting still works, instead of waiting for two FAILs (a
		// visible outage window). autoReblessTrigger canary-verifies the new
		// session before swapping, so a failed rotation is a no-op.
		if age := time.Since(time.UnixMilli(s.BlessedAt)); age >= qfarmPreAge {
			logOperational(fmt.Sprintf("[QFarm] Q alive but %.0fm old (≥ %s) — rotating proactively", age.Minutes(), qfarmPreAge))
			autoReblessTrigger(cfg)
		} else {
			logInfo(fmt.Sprintf("[AutoRebless] probe PASS (Q=%s) — alive", shortQ(s.Q)))
			// QFARM boot refill: a freshly-started proxy has an empty reserve
			// (the Q is young so no rotation will happen for ~70m). Top it up
			// now on the first proven-live Q so the mint fallback exists from
			// the first minutes of uptime instead of after the first swap.
			if n, err := reserveTokenCount(); err == nil && n < qfarmReserveTarget {
				go qfarmRefillReserveTarget(s.Q, cfg.ReserveTarget)
			}
		}
		return
	}

	autoReblessFailCount++
	logOperational(fmt.Sprintf("[AutoRebless] probe FAIL (%d/%d) — Q=%s degrading",
		autoReblessFailCount, cfg.DegradingThreshold, shortQ(s.Q)))

	if autoReblessFailCount >= cfg.DegradingThreshold {
		logOperational(fmt.Sprintf("[AutoRebless] threshold reached (%d FAILs) — triggering rebless",
			autoReblessFailCount))
		thresholdReached = true
	}
	if thresholdReached {
		// Production-only backoff gate (ProbeInterval < 1m means tests: never block).
		if cfg.ProbeInterval >= time.Minute {
			if rem := autoReblessBackoffRemaining(cfg, time.Now()); rem > 0 {
				logInfo(fmt.Sprintf("[AutoRebless] rebless backoff: next attempt in %s (%d consecutive failed rebless attempts)",
					rem.Round(time.Second), autoReblessTriggers))
				return
			}
		}
		autoReblessTrigger(cfg)
	}
}

// autoReblessMaxBackoff caps the exponential gap between rebless attempts.
const autoReblessMaxBackoff = 2 * time.Hour

// autoReblessBackoffRemaining returns how long to wait before the next
// rebless attempt. Consecutive failed triggers double the required gap
// (starting at ProbeInterval, capped at autoReblessMaxBackoff) so a broken
// q-bless (missing Chromium, WAF block, upstream flow change) degrades to a
// slow retry cadence instead of spawning Chrome every probe cycle forever.
func autoReblessBackoffRemaining(cfg AutoReblessConfig, now time.Time) time.Duration {
	autoReblessMu.Lock()
	defer autoReblessMu.Unlock()
	if autoReblessTriggers <= 0 || autoReblessLastTrigger.IsZero() {
		return 0
	}
	gap := cfg.ProbeInterval
	for i := 1; i < autoReblessTriggers && gap < autoReblessMaxBackoff; i++ {
		gap *= 2
	}
	if gap > autoReblessMaxBackoff {
		gap = autoReblessMaxBackoff
	}
	rem := gap - now.Sub(autoReblessLastTrigger)
	if rem < 0 {
		return 0
	}
	return rem
}

// autoReblessInProcessCanary mints one token via qmintMint and runs it
// through tryCompute (initCaptcha + verifyCaptcha) — NO Chrome subprocess.
// Returns true if the Q verifies successfully, false otherwise.
//
// IMPORTANT: this consumes one device token from the blessed session, which
// is the same cost as a real request. We accept this because the alternative
// (spawning Chrome just to probe) is far more expensive.
func autoReblessInProcessCanary(ctx context.Context, s *blessSession, timeout time.Duration) bool {
	type result struct {
		payload string
		err     error
	}
	ch := make(chan result, 1)
	go func() {
		token, ok, err := qmintMint()
		if err != nil || !ok {
			ch <- result{"", err}
			return
		}
		payload, err := tryCompute(token)
		ch <- result{payload, err}
	}()

	select {
	case r := <-ch:
		if r.err != nil {
			logError(fmt.Sprintf("[AutoRebless] canary error: %v", r.err))
			return false
		}
		return r.payload != ""
	case <-ctx.Done():
		logError(fmt.Sprintf("[AutoRebless] canary timeout after %s", timeout))
		return false
	}
}

// --- rebless subprocess --------------------------------------------------

// autoReblessTrigger spawns the q-bless binary to re-bless the session,
// writing to a temp file. On success (canary PASS on the new session), it
// atomically swaps the new qbless.json into place.
func autoReblessTrigger(cfg AutoReblessConfig) {
	autoReblessMu.Lock()
	if autoReblessReblessing {
		autoReblessMu.Unlock()
		return // already reblessing
	}
	autoReblessReblessing = true
	autoReblessMu.Unlock()
	defer func() {
		autoReblessMu.Lock()
		autoReblessReblessing = false
		autoReblessMu.Unlock()
	}()
	success := false
	defer func() {
		autoReblessMu.Lock()
		if success {
			autoReblessTriggers = 0
		} else {
			autoReblessTriggers++
		}
		autoReblessLastTrigger = time.Now()
		autoReblessMu.Unlock()
	}()

	binary := cfg.QblessBinary
	if _, err := exec.LookPath(binary); err != nil {
		// Resolve fallbacks in order: repo-relative, next to the session file
		// being used (a moved/renamed bundle dir left the env path stale in
		// the 2026-09-10 outage), then the user config dir (where start.sh
		// installs it).
		candidates := []string{filepath.Join(".", binary)}
		if sf := qblessFile(); sf != "" {
			candidates = append(candidates, filepath.Join(filepath.Dir(sf), "q-bless"))
		}
		if home, err2 := os.UserHomeDir(); err2 == nil && home != "" {
			candidates = append(candidates, filepath.Join(home, ".config", "zai-proxy", "q-bless"))
		}
		found := false
		for _, c := range candidates {
			if _, err3 := os.Stat(c); err3 == nil {
				binary = c
				found = true
				break
			}
		}
		if !found {
			logError(fmt.Sprintf("[AutoRebless] q-bless binary not found: %s nor %v (set QBLESS_BINARY)", cfg.QblessBinary, candidates))
			return
		}
	}

	tmpFile, err := os.CreateTemp("", "qbless-auto-*.json")
	if err != nil {
		logError(fmt.Sprintf("[AutoRebless] temp file error: %v", err))
		return
	}
	tmpPath := tmpFile.Name()
	tmpFile.Close()
	defer os.Remove(tmpPath) // cleanup on failure

	ctx, cancel := context.WithTimeout(context.Background(), cfg.ReblessTimeout)
	defer cancel()

	logOperational(fmt.Sprintf("[AutoRebless] spawning %s -out %s …", binary, tmpPath))
	cmd := exec.CommandContext(ctx, binary, "-out", tmpPath)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		logError(fmt.Sprintf("[AutoRebless] q-bless subprocess failed: %v", err))
		return
	}

	// Verify the new session with a canary before swapping.
	raw, err := os.ReadFile(tmpPath)
	if err != nil {
		logError(fmt.Sprintf("[AutoRebless] read new session error: %v", err))
		return
	}
	var newSession blessSession
	if err := json.Unmarshal(raw, &newSession); err != nil || newSession.Q == "" {
		logError(fmt.Sprintf("[AutoRebless] new session malformed: %v", err))
		return
	}

	logInfo(fmt.Sprintf("[AutoRebless] new session blessed (Q=%s) — verifying canary before swap", shortQ(newSession.Q)))

	// Temporarily point QBLESS_FILE at the temp file so qmintMint/tryCompute
	// uses the new session for the canary. We hold autoReblessProbeMu so no
	// live request races with this env swap.
	autoReblessProbeMu.Lock()
	origEnv := os.Getenv("QBLESS_FILE")
	os.Setenv("QBLESS_FILE", tmpPath)
	// Clear cache so qblessLoad reads the new file.
	qblessMu.Lock()
	qblessLoaded = nil
	qblessChecked = time.Time{}
	qblessMu.Unlock()

	verifyCtx, verifyCancel := context.WithTimeout(context.Background(), 30*time.Second)
	pass := autoReblessInProcessCanary(verifyCtx, &newSession, 30*time.Second)
	verifyCancel()

	// Restore env + clear cache so subsequent reads pick up the real file.
	if origEnv == "" {
		os.Unsetenv("QBLESS_FILE")
	} else {
		os.Setenv("QBLESS_FILE", origEnv)
	}
	qblessMu.Lock()
	qblessLoaded = nil
	qblessChecked = time.Time{}
	qblessMu.Unlock()
	autoReblessProbeMu.Unlock()

	if !pass {
		logError("[AutoRebless] new session canary FAIL — NOT swapping (keeping old session)")
		return
	}

	// Atomic swap: rename tmp → qblessFile()
	target := qblessFile()
	if target == "" {
		target = "qbless.json"
	}
	if err := os.Rename(tmpPath, target); err != nil {
		logError(fmt.Sprintf("[AutoRebless] swap error: %v", err))
		return
	}

	// Force qblessLoad to re-read the new file on next call.
	qblessMu.Lock()
	qblessLoaded = nil
	qblessChecked = time.Time{}
	qblessMu.Unlock()

	// Reset health tracker so the new Q starts fresh.
	qblessSessionReset()
	autoReblessFailCount = 0

	// QFARM: after a swap, clear + refill the reserve on the NEW Q. Tokens
	// are signed with the Q they were minted on (md5 includes Q), so old
	// reserve entries are almost certainly invalid once their Q is rotated
	// out — topping up would keep dead tokens and burn breaker budget in the
	// next outage. Refilling happens on a freshly canary-proven Q (CPU-only
	// mint, ~0ms/token), so the clear+refill window is effectively safe.
	go qfarmRefillFresh(newSession.Q, cfg.ReserveTarget)

	success = true
	logOperational(fmt.Sprintf("[AutoRebless] ✅ Q reblessed and swapped — new Q=%s", shortQ(newSession.Q)))
}

// qfarmRefillReserve tops up the emergency reserve to qfarmReserveTarget
// tokens, minted on the CURRENT blessed Q (which the caller has just proven
// live). Runs in its own goroutine; each mint is CPU-only (~0ms), so this
// is fast. Failures are logged and never fatal — an empty reserve is an
// outage risk, not an outage.
func qfarmRefillReserve(q string) {
	qfarmRefillReserveTarget(q, qfarmReserveTarget)
}

// qfarmRefillReserveTarget tops the reserve up to an explicit target
// (QFARM_RESERVE_TARGET, default qfarmReserveTarget).
func qfarmRefillReserveTarget(q string, target int) {
	n, err := reserveTokenCount()
	if err != nil {
		logError("[QFarm] reserve count failed: " + err.Error())
		return
	}
	need := target - n
	if need <= 0 {
		logInfo(fmt.Sprintf("[QFarm] reserve already stocked (%d tokens) — no refill needed", n))
		return
	}
	for i := 0; i < need; i++ {
		tok, ok, err := qmintMint()
		if err != nil || !ok {
			logError(fmt.Sprintf("[QFarm] refill mint %d/%d failed (ok=%v err=%v) — stopping", i+1, need, ok, err))
			return
		}
		if err := reserveAddToken(tok); err != nil {
			logError("[QFarm] reserve insert failed: " + err.Error())
			return
		}
	}
	logOperational(fmt.Sprintf("[QFarm] reserve refilled to %d tokens on Q=%s", target, shortQ(q)))
}

// reserveTokenCount returns the number of tokens in the emergency reserve.
func reserveTokenCount() (int, error) {
	dbMu.Lock()
	defer dbMu.Unlock()
	if globalDB == nil {
		return 0, errors.New("reserve DB not initialized")
	}
	var n int
	if err := globalDB.QueryRow("SELECT COUNT(*) FROM tokens;").Scan(&n); err != nil {
		return 0, err
	}
	return n, nil
}

// reserveAddToken inserts one single-use token into the emergency reserve.
func reserveAddToken(tok string) error {
	dbMu.Lock()
	defer dbMu.Unlock()
	if globalDB == nil {
		return errors.New("reserve DB not initialized")
	}
	_, err := globalDB.Exec("INSERT INTO tokens (token, batch) VALUES (?, 0);", tok)
	return err
}

// reserveClearTokens removes every reserve token (used after a Q swap —
// see qfarmRefillFresh).
func reserveClearTokens() error {
	dbMu.Lock()
	defer dbMu.Unlock()
	if globalDB == nil {
		return errors.New("reserve DB not initialized")
	}
	_, err := globalDB.Exec("DELETE FROM tokens;")
	return err
}

// qfarmRefillFresh clears stale (old-Q) reserve tokens and refills the
// reserve to target on the new Q, in one pass. Only called on the success
// path of a rebless: the new Q is canary-proven, so minting can't fail the
// way it does on a dying Q.
func qfarmRefillFresh(q string, target int) {
	if err := reserveClearTokens(); err != nil {
		logError("[QFarm] reserve clear failed: " + err.Error())
		return
	}
	qfarmRefillReserveTarget(q, target)
}

// shortQ returns the first 12 chars of Q for log-friendly display.
func shortQ(q string) string {
	if len(q) <= 12 {
		return q
	}
	return q[:12] + "…"
}

// --- status endpoint ------------------------------------------------------

// qfarmStatusHandler answers GET /api/qfarm with the QFarm state an operator
// needs at a glance: which Q is live, how old, whether it's marked dead, how
// deep the emergency reserve is, breaker state, and the last rebless time.
// Exposed so an operator (or a monitor) can see a rotation coming BEFORE it
// becomes an outage.
func qfarmStatusHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}
	s := qblessLoad()
	resp := map[string]interface{}{
		"auto_rebless_enabled": os.Getenv("QBLESS_AUTO_REBLESS") != "0",
	}
	if s != nil {
		age := time.Since(time.UnixMilli(s.BlessedAt))
		resp["q"] = map[string]interface{}{
			"id":              shortQ(s.Q),
			"age_minutes":     int(age.Minutes()),
			"dead":            qblessQDead(s.Q),
			"pre_age_minutes": int(qfarmPreAge.Minutes()),
			"rotating_soon":   age >= qfarmPreAge,
		}
	} else {
		resp["q"] = nil
	}
	if n, err := reserveTokenCount(); err == nil {
		resp["reserve_tokens"] = n
		resp["reserve_target"] = qfarmReserveTarget
	} else {
		resp["reserve_tokens"] = nil
	}
	resp["captcha_breaker_open"] = captchaBreakerOpen()
	writeJSON(w, 200, resp)
}
